using namespace std;using ll=long long;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);
int n;cin>>n;vector<ll>a(n);ll sum=0;for(auto &x:a){cin>>x;sum+=x;}if(n<3||sum%3){cout<<"NO\n";return 0;}sort(a.rbegin(),a.rend());ll target=sum/3;vector<ll>b(3);function<bool(int)>f=[&](int i){if(i==n)return true;set<ll>seen;for(int k=0;k<3;k++)if(b[k]+a[i]<=target&&seen.insert(b[k]).second){b[k]+=a[i];if(f(i+1))return true;b[k]-=a[i];}return false;};cout<<(f(0)?"YES":"NO")<<'\n';
}
